public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0) {
        return 0;
    }

    int rows = grid.length;
    int cols = grid[0].length;
    int count = 0;

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (grid[i][j] == '@') {
                count++;
                // Use BFS/DFS to mark the entire deposit as visited
                // Here we use BFS to avoid stack overflow for large grids
                java.util.Queue<int[]> queue = new java.util.LinkedList<>();
                queue.offer(new int[]{i, j});
                grid[i][j] = '&'; // Mark as visited
                while (!queue.isEmpty()) {
                    int[] cell = queue.poll();
                    int r = cell[0];
                    int c = cell[1];
                    // Check all 8 directions (including diagonals) since oil deposits are connected diagonally
                    int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};
                    int[] dc = {-1, 0, 1, -1, 1, -1, 0, 1};
                    for (int d = 0; d < 8; d++) {
                        int nr = r + dr[d];
                        int nc = c + dc[d];
                        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == '@') {
                            grid[nr][nc] = '&'; // Mark as visited
                            queue.offer(new int[]{nr, nc});
                        }
                    }
                }
            }
        }
    }

    return count;
}
