public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Create adjacency list
    List<List<Integer>> adj = new ArrayList<>();
    for (int i = 0; i <= n; i++) {
        adj.add(new ArrayList<>());
    }

    // Build adjacency list from paths
    for (int[] path : paths) {
        int u = path[0];
        int v = path[1];
        adj.get(u).add(v);
        adj.get(v).add(u);
    }

    // BFS to check if start can reach end
    int startX = start[0];
    int startY = start[1];
    int endX = end[0];
    int endY = end[1];

    // Assuming the n-tersections are numbered from 0 to n*n-1
    // Convert (row, col) to index
    int startIndex = startX * n + startY;
    int endIndex = endX * n + endY;

    if (startIndex == endIndex) {
        return "can be travelled";
    }

    // BFS
    boolean[] visited = new boolean[n * n];
    Queue<Integer> queue = new LinkedList<>();
    queue.offer(startIndex);
    visited[startIndex] = true;

    while (!queue.isEmpty()) {
        int curr = queue.poll();
        if (curr == endIndex) {
            return "can be travelled";
        }
    }

    // Redo BFS properly with the adjacency built for n*n nodes
    // Wait, the paths are between n-tersections. The n-tersections are indexed 0 to n*n-1.
    // Let's rebuild the adjacency properly.

    // Reset
    adj.clear();
    for (int i = 0; i <= n * n; i++) {
        adj.add(new ArrayList<>());
    }

    for (int[] path : paths) {
        int u = path[0];
        int v = path[1];
        if (u < n * n && v < n * n) {
            adj.get(u).add(v);
            adj.get(v).add(u);
        }
    }

    // BFS
    visited = new boolean[n * n];
    queue = new LinkedList<>();
    queue.offer(startIndex);
    visited[startIndex] = true;

    while (!queue.isEmpty()) {
        int curr = queue.poll();
        if (curr == endIndex) {
            return "can be travelled";
        }
        for (int next : adj.get(curr)) {
            if (!visited[next]) {
                visited[next] = true;
                queue.offer(next);
            }
        }
    }

    return "cannot be travelled";
}
