public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Build the adjacency list representation of the tree
    List<List<Integer>> adj = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        adj.add(new ArrayList<>());
    }
    for (int[] edge : edges) {
        int u = edge[0], v = edge[1];
        adj.get(u).add(v);
        adj.get(v).add(u);
    }

    // Do a DFS from node 0 to calculate the minimum time
    return dfs(0, -1, adj, hasApple);
}

private int dfs(int node, int parent, List<List<Integer>> adj, boolean[] hasApple) {
    int total = 0;

    for (int neighbor : adj.get(node)) {
        if (neighbor != parent) {
            int timeToChild = dfs(neighbor, node, adj, hasApple);
            // If we need to visit the child (either it has an apple or a descendant does), 
            // we add 2 to the time: 1 to go to the child and 1 to come back.
            if (timeToChild > 0 || hasApple[neighbor]) {
                total += 2 + timeToChild;
            }
        }
    }

    return total;
}
