public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;

    int sum = 0;
    for (int num : nums) sum += num;

    // To have same average, sum of first subarray / k == sum of second subarray / (n-k)
    // So sum_first * (n-k) == sum_second * k
    // sum_first * n == sum * k
    // So sum must be divisible by k, and sum_first = sum * k / n
    // This means sum * k must be divisible by n

    // We can iterate over possible sizes of first subarray k from 1 to n/2
    // For each k, check if sum * k % n == 0, and if the target sum (sum * k / n)
    // can be formed by a subarray of size k

    // Use meet-in-the-middle approach for efficiency when n is up to 20 (typical for this problem)
    // But for larger n, we might need a different approach. Let's assume n <= 20.

    // Meet in the middle
    int half = n / 2;
    int[] left = Arrays.copyOfRange(nums, 0, half);
    int[] right = Arrays.copyOfRange(nums, half, n);

    // For the right half, store for each count (number of elements chosen), the set of sums
    HashSet<Integer>[] rightSums = new HashSet[half + 1];
    for (int i = 0; i <= half; i++) {
        rightSums[i] = new HashSet<>();
    }

    // Generate all subsets of right half
    int rightSize = right.length;
    for (int mask = 0; mask < (1 << rightSize); mask++) {
        int count = 0;
        int s = 0;
        for (int i = 0; i < rightSize; i++) {
            if ((mask & (1 << i)) != 0) {
                count++;
                s += right[i];
            }
        }
        rightSums[count].add(s);
    }

    // Now iterate over possible k from 1 to n-1, but we only need to check k <= n/2
    // Actually, due to symmetry, if a split of size k works, a split of size n-k also works with the same target sum scaled.
    // But here the target sum is sum * k / n, so we only need to check k from 1 to n/2 (inclusive)

    for (int k = 1; k <= n / 2; k++) {
        // Check if sum * k is divisible by n
        if (sum * k % n != 0) continue;
        int target = sum * k / n;

        // Check if we can form target sum with exactly k elements
        // Iterate over i = number of elements from left (i can be 0 to k, and also i <= half)
        // The remaining (k - i) elements must come from right
        for (int i = 0; i <= Math.min(k, half); i++) {
            int j = k - i;
            if (j > half) continue; // Can't take more than half from right
            // Iterate over all subsets of left of size i
            int leftSize = left.length;
            for (int mask = 0; mask < (1 << leftSize); mask++) {
                int count = 0;
                int s = 0;
                for (int idx = 0; idx < leftSize; idx++) {
                    if ((mask & (1 << idx)) != 0) {
                        count++;
                        s += left[idx];
                    }
                }
                if (count != i) continue;
                int remainingTarget = target - s;
                if (rightSums[j].contains(remainingTarget)) {
                    return true;
                }
            }
        }
    }

    return false;
}
