    public int minCostClimbingStairs(int[] cost) {
        if (cost == null || cost.length == 0) {
            return 0;
        }

        int n = cost.length;
        if (n == 1) {
            return cost[0];
        }

        // dp[i] represents the minimum cost to reach the i-th step
        // We can either come from i-1 or i-2
        // To reach the top (which is step n), we can come from step n-1 or step n-2

        int prev2 = 0;      // dp[i-2]
        int prev1 = 0;      // dp[i-1]

        // We want to compute dp up to n (the top)
        // dp[0] = 0 (starting at step 0 costs 0 to get there)
        // dp[1] = 0 (starting at step 1 costs 0 to get there)
        // dp[i] = min(dp[i-1] + cost[i-1], dp[i-2] + cost[i-2]) for i >= 2

        for (int i = 2; i <= n; i++) {
            int current = Math.min(prev1 + cost[i - 1], prev2 + cost[i - 2]);
            prev2 = prev1;
            prev1 = current;
        }

        return prev1;
    }
