public boolean hasAllCodes(String s, int k) {
    if (k == 0) return true;
    int n = s.length();
    if (n < k) return false;
    if (n - k + 1 < (1 << k)) return false;

    java.util.Set<Integer> seen = new java.util.HashSet<>();
    int mask = (1 << k) - 1;
    int val = 0;

    for (int i = 0; i < n; i++) {
        val = ((val << 1) | (s.charAt(i) - '0')) & mask;
        if (i >= k - 1) {
            seen.add(val);
            if (seen.size() == (1 << k)) {
                return true;
            }
        }
    }
    return false;
}
