    int top = -1;

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        // Check if the current character cancels with the top of stack
        if (top >= 0) {
            int diff = Math.abs(c - stack[top]);
            // 'a' to 'z' are consecutive in ASCII, 'A' to 'Z' are consecutive
            // The difference between corresponding upper and lower case is 32
            // e.g., 'A' = 65, 'a' = 97, difference = 32
            // So if the absolute difference is 32 and they are different cases, they cancel.
            // Since one must be lower and one upper, and abs diff is 32, that's the condition.
            if (diff == 32) {
                top--; // Pop the top
                continue;
            }
        }
        stack[++top] = c;
    }

    return new String(stack, 0, top + 1);
