public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n <= 1) return 1;

    // Backtracking with visited array
    int[] visited = new int[n];
    int count = 0;

    for (int i = 0; i < n; i++) {
        // Skip duplicate starts to avoid counting identical permutations multiple times
        if (i > 0 && A[i] == A[i - 1]) continue;

        visited[i] = 1;
        count += backtrack(A, visited, 1, A[i], n);
        visited[i] = 0;
    }

    return count;
}

private static int backtrack(int[] A, int[] visited, int depth, int prev, int n) {
    if (depth == n) {
        return 1;
    }

    int count = 0;
    for (int i = 0; i < n; i++) {
        if (visited[i] == 1) continue;

        // Skip duplicates at the same depth
        if (i > 0 && A[i] == A[i - 1] && visited[i - 1] == 0) continue;

        // Check if sum of previous element and current element is a perfect square
        if (isPerfectSquare(prev + A[i])) {
            visited[i] = 1;
            count += backtrack(A, visited, depth + 1, A[i], n);
            visited[i] = 0;
        }
    }

    return count;
}

private static boolean isPerfectSquare(int num) {
    if (num == 0) return true;
    int sqrt = (int) Math.sqrt(num);
    return sqrt * sqrt == num;
}

