        return new int[0];
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int totalElements = rows * cols;
    int[] result = new int[totalElements];

    int index = 0;
    int m = rows + cols - 1;

    for (int sum = 0; sum < m; sum++) {
        if (sum % 2 == 0) {
            // Even sum: traverse from bottom-left to top-right (i decreases, j increases)
            // i ranges from min(rows-1, sum) down to max(0, sum - cols + 1)
            int startI = Math.min(rows - 1, sum);
            int endI = Math.max(0, sum - cols + 1);
            for (int i = startI; i >= endI; i--) {
                int j = sum - i;
                result[index++] = mat[i][j];
            }
        } else {
            // Odd sum: traverse from top-right to bottom-left (i increases, j decreases)
            // i ranges from max(0, sum - cols + 1) to min(rows-1, sum)
            int startI = Math.max(0, sum - cols + 1);
            int endI = Math.min(rows - 1, sum);
            for (int i = startI; i <= endI; i++) {
                int j = sum - i;
                result[index++] = mat[i][j];
            }
        }
    }

    return result;
