public static int findSmallestInteger(int n) {
    char[] digits = String.valueOf(n).toCharArray();
    int len = digits.length;

    // Step 1: Find the rightmost digit that is smaller than the digit to its right
    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }

    // If no such digit found, the number is the largest possible with these digits
    if (i < 0) {
        return -1;
    }

    // Step 2: Find the smallest digit to the right of i that is greater than digits[i]
    int j = len - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }

    // Step 3: Swap digits[i] and digits[j]
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Step 4: Reverse the suffix starting at i+1 to get the smallest lexicographical order
    int left = i + 1;
    int right = len - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }

    // Convert back to int
    String result = new String(digits);
    try {
        int num = Integer.parseInt(result);
        return num;
    } catch (NumberFormatException e) {
        return -1;
    }
