    public static int minPerfectSquareSum(int n) {
        // Lagrange's Four-Square Theorem: every natural number is the sum of four squares.
        // The answer is at most 4.
        // If n is a perfect square, the answer is 1.
        // If n can be written as the sum of two perfect squares, the answer is 2.
        // Otherwise, the answer is either 3 or 4.
        // By Legendre's three-square theorem, n is not representable as the sum of three squares
        // iff n = 4^a * (8b + 7) for some integers a >= 0 and b >= 0.
        // In that case, the answer is 4.
        // Otherwise, the answer is 3.

        // Check for perfect square (answer 1)
        int sqrt = (int) Math.sqrt(n);
        if (sqrt * sqrt == n) {
            return 1;
        }

        // Check for sum of two perfect squares (answer 2)
        for (int i = 1; i <= sqrt; i++) {
            int remainder = n - i * i;
            int j = (int) Math.sqrt(remainder);
            if (j * j == remainder) {
                return 2;
            }
        }

        // Check if it's of the form 4^a * (8b + 7) (answer 4)
        int temp = n;
        while (temp % 4 == 0) {
            temp /= 4;
        }
        if (temp % 8 == 7) {
            return 4;
        }

        // Otherwise, answer is 3
        return 3;
    }
